package com.gorak.ecommerce;
import org.openqa.selenium.*;import org.openqa.selenium.chrome.ChromeDriver;import org.openqa.selenium.chrome.ChromeOptions;import org.openqa.selenium.support.ui.WebDriverWait;import org.testng.Assert;import org.testng.ITestResult;import org.testng.annotations.*;import java.io.File;import java.nio.file.*;import java.time.Duration;
public class StoreE2ETest {private WebDriver driver;private String baseUrl;
@BeforeMethod public void setUp(){baseUrl=System.getProperty("baseUrl","http://localhost:8080");ChromeOptions options=new ChromeOptions();if(Boolean.getBoolean("headless"))options.addArguments("--headless=new");options.addArguments("--window-size=1440,1000");driver=new ChromeDriver(options);}
@AfterMethod(alwaysRun=true) public void tearDown(ITestResult result){if(driver!=null){if(!result.isSuccess())captureFailure(result.getName());driver.quit();}}
@Test public void productListAndSearchWork(){driver.get(baseUrl);new WebDriverWait(driver,Duration.ofSeconds(10)).until(d->d.findElements(By.cssSelector("[data-testid='product-card']")).size()==4);Assert.assertEquals(driver.findElements(By.cssSelector("[data-testid='product-card']")).size(),4);driver.findElement(By.cssSelector("[data-testid='product-search']")).sendKeys("headphones");Assert.assertEquals(driver.findElements(By.cssSelector("[data-testid='product-card']")).size(),1);Assert.assertTrue(driver.getPageSource().contains("Wireless Headphones"));}
@Test public void addToCartAndCheckoutCreateOrder(){driver.get(baseUrl);new WebDriverWait(driver,Duration.ofSeconds(10)).until(d->d.findElements(By.cssSelector("[data-testid='add-to-cart']")).size()==4);driver.findElement(By.cssSelector("[data-testid='add-to-cart']")).click();Assert.assertEquals(driver.findElement(By.cssSelector("[data-testid='cart-count']")).getText(),"Cart: 1");driver.findElement(By.cssSelector("[data-testid='customer-name']")).sendKeys("QA Demo");driver.findElement(By.cssSelector("[data-testid='customer-email']")).sendKeys("qa.demo@example.com");driver.findElement(By.cssSelector("[data-testid='checkout-submit']")).click();WebElement confirmation=new WebDriverWait(driver,Duration.ofSeconds(10)).until(d->d.findElement(By.cssSelector("[data-testid='order-confirmation']")));Assert.assertTrue(confirmation.getText().contains("Order confirmed"));}
@Test public void emptyCartCheckoutShowsValidationMessage(){driver.get(baseUrl);driver.findElement(By.cssSelector("[data-testid='customer-name']")).sendKeys("QA Demo");driver.findElement(By.cssSelector("[data-testid='customer-email']")).sendKeys("qa.demo@example.com");driver.findElement(By.cssSelector("[data-testid='checkout-submit']")).click();Assert.assertTrue(driver.findElement(By.id("message")).getText().contains("add at least one product"));}
private void captureFailure(String name){try{Path dir=Path.of("evidence","screenshots");Files.createDirectories(dir);File src=((TakesScreenshot)driver).getScreenshotAs(OutputType.FILE);Files.copy(src.toPath(),dir.resolve(name.replaceAll("[^A-Za-z0-9_-]","_")+"-failure.png"),StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){System.err.println("Screenshot capture failed: "+e.getMessage());}}}
